glsl1.vert:
precision highp float;
uniform highp mat4 cc_matViewProj;
#if USE_LOCAL
 uniform highp mat4 cc_matWorld;
#endif
attribute vec3 a_position;
attribute vec2 a_texCoord;
attribute vec4 a_color;
varying vec2 uv0;
varying vec4 color;
#if USE_FOCUS
  uniform vec4 uvBounds;
  uniform vec4 focusParams;
  uniform vec4 focusAxes;
#endif
vec4 vert(){vec4 p=vec4(a_position,1.0);
#if USE_LOCAL
p=cc_matWorld*p;
#endif
#if USE_FOCUS
vec2 q=(a_texCoord-uvBounds.xy)/max(uvBounds.zw-uvBounds.xy,vec2(0.000001));
p.xy+=focusParams.w*(focusAxes.xy*(q.x*2.0-1.0)+focusAxes.zw*(1.0-q.y*2.0));
#endif
uv0=a_texCoord;color=a_color;return cc_matViewProj*p;}
void main() { gl_Position = vert(); }

glsl1.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture2D(tex, uv).rgb, texture2D(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture2D(tex, uv);
#endif
}
varying vec2 uv0;
varying vec4 color;
uniform sampler2D cc_spriteTexture;
  uniform vec4 outlineColor;
  uniform vec4 outlineStep;
  uniform vec4 uvBounds;
  uniform vec4 focusParams;
  uniform vec4 plateTone;
vec3 tintPlate(vec3 source){return mix(source,plateTone.rgb*(0.55+0.7*dot(source,vec3(0.299,0.587,0.114))),plateTone.a);}
float sampleAlpha(vec2 p){vec2 low=step(uvBounds.xy,p),high=step(p,uvBounds.zw);return CCSampleWithAlphaSeparated(cc_spriteTexture,clamp(p,uvBounds.xy,uvBounds.zw)).a*low.x*low.y*high.x*high.y;}
vec4 frag(){
 #if USE_FOCUS
 vec2 extent=max(uvBounds.zw-uvBounds.xy,vec2(0.000001));
 vec2 q=((uv0-uvBounds.xy)/extent-0.5)*focusParams.xy+0.5;
 vec2 p=uvBounds.xy+q*extent;
 float a=sampleAlpha(p);
 vec3 source=CCSampleWithAlphaSeparated(cc_spriteTexture,clamp(p,uvBounds.xy,uvBounds.zw)).rgb;
 #if USE_PLATE_TINT
 source=tintPlate(source);
 #endif
 float nearRing=0.0,midRing=0.0,farRing=0.0;
 #if USE_STICKER || USE_SOLID_FOCUS
 for(int i=0;i<16;i++){
  float angle=float(i)*0.392699082;
  vec2 direction=vec2(cos(angle),sin(angle));
  nearRing=max(nearRing,sampleAlpha(p+direction*outlineStep.xy*extent));
  nearRing=max(nearRing,sampleAlpha(p+direction*outlineStep.xy*extent*0.5));
 }
 #else
 for(int i=0;i<8;i++){
  float angle=float(i)*0.785398163;
  vec2 direction=vec2(cos(angle),sin(angle));
  nearRing=max(nearRing,sampleAlpha(p+direction*outlineStep.xy*extent));
  midRing+=sampleAlpha(p+direction*outlineStep.zw*extent*0.45)*0.125;
  farRing+=sampleAlpha(p+direction*outlineStep.zw*extent)*0.125;
 }
 #endif
 float border=(nearRing*outlineColor.a+(midRing*0.72+farRing*0.28)*focusParams.z)*(1.0-a);
 border=min(border,1.0-a);
 float alpha=a+border;
 return vec4((source*a+outlineColor.rgb*border)/max(alpha,0.00001),alpha)*color;
 #else
 vec4 src=CCSampleWithAlphaSeparated(cc_spriteTexture,uv0);
 #if USE_PLATE_TINT
 return vec4(tintPlate(src.rgb),src.a)*color;
 #else
 vec2 d=outlineStep.xy;
 float ring=max(max(sampleAlpha(uv0+vec2(d.x,0.0)),sampleAlpha(uv0-vec2(d.x,0.0))),max(sampleAlpha(uv0+vec2(0.0,d.y)),sampleAlpha(uv0-vec2(0.0,d.y))));
 vec2 diagonal=d*0.7071;
 ring=max(ring,max(max(sampleAlpha(uv0+diagonal),sampleAlpha(uv0-diagonal)),max(sampleAlpha(uv0+vec2(diagonal.x,-diagonal.y)),sampleAlpha(uv0+vec2(-diagonal.x,diagonal.y)))));
 float border=ring*outlineColor.a*(1.0-src.a),alpha=src.a+border;
 vec3 rgb=(src.rgb*src.a+outlineColor.rgb*border)/max(alpha,0.00001);
 #if IS_GRAY
  rgb=vec3(dot(rgb,vec3(0.2126,0.7152,0.0722)));
 #endif
 return vec4(rgb,alpha)*color;
 #endif
 #endif
}
void main() { gl_FragColor = frag(); }

glsl1.vert:
precision highp float;
uniform highp mat4 cc_matViewProj;
#if USE_LOCAL
 uniform highp mat4 cc_matWorld;
#endif
attribute vec3 a_position;
attribute vec2 a_texCoord;
attribute vec4 a_color;
varying vec2 uv0;
varying vec4 color;
#if USE_STICKER
  uniform vec4 uvBounds;
  uniform vec4 expansion;
  uniform vec4 axes;
#endif
vec4 vert(){vec4 p=vec4(a_position,1.0);
#if USE_LOCAL
p=cc_matWorld*p;
#endif
#if USE_STICKER
vec2 q=(a_texCoord-uvBounds.xy)/max(uvBounds.zw-uvBounds.xy,vec2(0.000001));
p.xy+=expansion.w*(axes.xy*(q.x*2.0-1.0)+axes.zw*(1.0-q.y*2.0));
#endif
uv0=a_texCoord;color=a_color;return cc_matViewProj*p;}
void main() { gl_Position = vert(); }

glsl1.frag:
precision highp float;
vec4 CCSampleWithAlphaSeparated(sampler2D tex, vec2 uv) {
#if CC_USE_EMBEDDED_ALPHA
  return vec4(texture2D(tex, uv).rgb, texture2D(tex, uv + vec2(0.0, 0.5)).r);
#else
  return texture2D(tex, uv);
#endif
}
varying vec2 uv0;
varying vec4 color;
uniform sampler2D cc_spriteTexture;
uniform sampler2D outlineMask;
  uniform vec4 outlineColor;
  uniform vec4 uvBounds;
  uniform vec4 maskBounds;
  uniform vec4 expansion;
vec4 frag(){
 vec2 extent=max(uvBounds.zw-uvBounds.xy,vec2(0.000001));
 vec2 q=(uv0-uvBounds.xy)/extent;
 vec2 sourceQ=(q-0.5)*expansion.xy+0.5;
 vec2 p=uvBounds.xy+sourceQ*extent;
 vec4 src=CCSampleWithAlphaSeparated(cc_spriteTexture,clamp(p,uvBounds.xy,uvBounds.zw));
 vec2 low=step(vec2(0.0),sourceQ),high=step(sourceQ,vec2(1.0));src.a*=low.x*low.y*high.x*high.y;
 float ring=texture2D(outlineMask,mix(maskBounds.xy,maskBounds.zw,q)).a;
 float border=ring*outlineColor.a*(1.0-src.a),alpha=src.a+border;
 vec3 rgb=(src.rgb*src.a+outlineColor.rgb*border)/max(alpha,0.00001);
 #if IS_GRAY
  rgb=vec3(dot(rgb,vec3(0.2126,0.7152,0.0722)));
 #endif
 return vec4(rgb,alpha)*color;
}
void main() { gl_FragColor = frag(); }
